('Mitos atau Fakta: Hewan Nokturnal', 'Uji pengetahuanmu! Geser ke kanan jika FAKTA, ke kiri jika MITOS.', 'game', 13, 3, 'truth_or_myth', '{"truth_or_myth": [{"statement": "Kelelawar sebenarnya buta dan hanya bergantung pada suara.", "isTruth": false}, {"statement": "Burung hantu dapat memutar kepalanya hingga 270 derajat.", "isTruth": true}, {"statement": "Kucing bisa melihat dalam kegelapan total tanpa cahaya sama sekali.", "isTruth": false}, {"statement": "Kunang-kunang menghasilkan cahaya untuk menarik pasangannya.", "isTruth": true}, {"statement": "Banteng akan marah jika melihat warna merah.", "isTruth": false}]}'),

('Tebak Kata Misteri (Wordle)', 'Pecahkan kode sains 5 huruf ini dalam 6 kali percobaan!', 'game', 14, 3, 'science_wordle', '{"science_wordle": {"word": "FOSIL", "clue": "Sisa-sisa makhluk hidup masa lalu yang membatu."}}'),

